import { store } from "../cache/store";

export function etaRoute(request) {
  const { from, to } = request.query;
  const cached = store.get(`${from}:${to}`);
  if (cached) return cached;
  const minutes = estimateMinutes(from, to);
  const eta = new Date(request.now + minutes * 60_000);
  store.set(`${from}:${to}`, { minutes, eta });
  return { minutes, eta };
}

function estimateMinutes(from, to) {
  return Math.round(distanceKm(from, to) * 1.6);
}

