src/cache/store.ts.content:
const MAX_ENTRIES = 500;
const entries = new Map();

export const store = {
  get(key) {
    return entries.get(key);
  },
  set(key, value) {
    if (entries.size >= MAX_ENTRIES) entries.delete(entries.keys().next().value);
    entries.set(key, value);
  },
};

